Actionscript.script:
if (_root.当前关卡名 != "地铁站")
{
	gotoAndPlay("skip1");
}

if (_parent.是否为敌人)
{
	_root.创建可拾取物("巨尸长斧",1,_parent._x,_parent._y,true);
}

if (_root.当前关卡名 != "地铁站")
{
	gotoAndPlay("skip2");
}

onClipEvent(load){
   声音 = "";
   霰弹值 = 2;
   子弹散射度 = 40;
   发射效果 = "";
   子弹种类 = "近战子弹";
   子弹威力 = _parent._parent.空手攻击力 * 10;
   子弹速度 = 2;
   击中地图效果 = "";
   Z轴攻击范围 = 60;
   击倒率 = 1;
   击中后子弹的效果 = "空手攻击火花";
   if(_parent._parent.是否为敌人 == true)
   {
      子弹敌我属性 = false;
   }
   else
   {
      子弹敌我属性 = true;
   }
   var myPoint = {x:this._x,y:this._y};
   _parent.localToGlobal(myPoint);
   _root.gameworld.globalToLocal(myPoint);
   shootX = myPoint.x;
   shootY = myPoint.y;
   _root.子弹区域shoot(声音,霰弹值,子弹散射度,发射效果,子弹种类,子弹威力,子弹速度,Z轴攻击范围,击中地图效果,_parent._parent._name,shootX,shootY,_parent._parent.Z轴坐标,子弹敌我属性,击倒率,击中后子弹的效果);
}

